#include <vector>
#include <algorithm>

long long fibonacci(int n) {
  if (n < 0) {
    throw std::invalid_argument("Input must be a non-negative integer.");
  }
  if (n <= 1) {
    return n;
  }
  std::vector<long long> fib(n + 1);
  fib[0] = 0;
  fib[1] = 1;
  for (int i = 2; i <= n; ++i) {
    fib[i] = fib[i - 1] + fib[i - 2];
  }
  return fib[n];
}


template <typename T>
void mergeSort(std::vector<T>& arr) {
    if (arr.size() <= 1) return;

    int mid = arr.size() / 2;
    std::vector<T> left(arr.begin(), arr.begin() + mid);
    std::vector<T> right(arr.begin() + mid, arr.end());

    mergeSort(left);
    mergeSort(right);

    int i = 0, j = 0, k = 0;
    while (i < left.size() && j < right.size()) {
        if (left[i] < right[j]) {
            arr[k++] = left[i++];
        } else {
            arr[k++] = right[j++];
        }
    }

    while (i < left.size()) {
        arr[k++] = left[i++];
    }
    while (j < right.size()) {
        arr[k++] = right[j++];
    }
}
